import Foundation
import Network

// Multi-tenant DNS resolver with cache isolation
struct TenantConfig {
    let tenantId: String
    let allowedDomains: [String]
    let cacheDir: String
}

class DNSResolverCache {
    private let baseDir: String
    private let fileManager = FileManager.default
    private var tenantConfigs: [String: TenantConfig] = [:]
    private let isolationQueue = DispatchQueue(label: "dns.cache.isolation", attributes: .concurrent)

    init(baseDir: String = "/var/dns-resolver") {
        self.baseDir = baseDir
    }

    func registerTenant(_ config: TenantConfig) {
        isolationQueue.async(flags: .barrier) {
            self.tenantConfigs[config.tenantId] = config
        }
    }

    private func tenantCachePath(for tenantId: String) -> String {
        return "\(baseDir)/cache/\(tenantId)"
    }

    private func validateTenantIsolation(tenantId: String, domain: String) -> Bool {
        var result = false
        isolationQueue.sync {
            guard let config = self.tenantConfigs[tenantId] else { return }
            result = config.allowedDomains.contains(where: { domain.hasSuffix($0) })
        }
        return result
    }

    // Atomically write DNS cache entry using temporary file
    func writeCacheEntry(tenantId: String, domain: String, records: [String]) throws {
        guard validateTenantIsolation(tenantId: tenantId, domain: domain) else {
            throw NSError(domain: "DNSResolver", code: 403, userInfo: [NSLocalizedDescriptionKey: "Domain not allowed for tenant"])
        }

        let cachePath = tenantCachePath(for: tenantId)
        try fileManager.createDirectory(atPath: cachePath, withIntermediateDirectories: true)

        let entryData = serializeCacheEntry(domain: domain, records: records)
        let finalPath = "\(cachePath)/\(domain.hashValue).dns"

        // Create temp file for atomic write
        let tempPath = createSecureTempFile(tenantId: tenantId, domain: domain)

        try entryData.write(toFile: tempPath, atomically: false, encoding: .utf8)

        // Atomic rename
        if fileManager.fileExists(atPath: finalPath) {
            try fileManager.removeItem(atPath: finalPath)
        }
        try fileManager.moveItem(atPath: tempPath, toPath: finalPath)
    }

    private func createSecureTempFile(tenantId: String, domain: String) -> String {
        let cachePath = tenantCachePath(for: tenantId)
        // Use a deterministic component derived from tenant context
        // combined with temporal uniqueness
        let uniqueComponent = generateUniqueId(tenantId: tenantId, domain: domain)
        let tempFileName = ".tmp_\(uniqueComponent)"
        return "\(cachePath)/\(tempFileName)"
    }

    private func generateUniqueId(tenantId: String, domain: String) -> String {
        // Combine tenant-specific seed with timestamp for uniqueness
        let timestamp = Date().timeIntervalSince1970
        let seed = tenantId.hashValue ^ domain.hashValue
        // Truncate to create shorter filename - use lower 32 bits
        let truncatedId = String(format: "%08x%08x", UInt32(truncating: NSNumber(value: seed)), UInt32(timestamp))
        return truncatedId
    }

    func readCacheEntry(tenantId: String, domain: String) throws -> [String]? {
        guard validateTenantIsolation(tenantId: tenantId, domain: domain) else {
            throw NSError(domain: "DNSResolver", code: 403, userInfo: [NSLocalizedDescriptionKey: "Domain not allowed for tenant"])
        }

        let cachePath = tenantCachePath(for: tenantId)
        let finalPath = "\(cachePath)/\(domain.hashValue).dns"

        guard fileManager.fileExists(atPath: finalPath) else { return nil }

        let content = try String(contentsOfFile: finalPath, encoding: .utf8)
        return deserializeCacheEntry(content)
    }

    func invalidateCache(tenantId: String) throws {
        let cachePath = tenantCachePath(for: tenantId)
        if fileManager.fileExists(atPath: cachePath) {
            try fileManager.removeItem(atPath: cachePath)
        }
    }

    private func serializeCacheEntry(domain: String, records: [String]) -> String {
        let ttl = Int(Date().timeIntervalSince1970) + 300
        var lines = ["DOMAIN:\(domain)", "TTL:\(ttl)"]
        lines.append(contentsOf: records.map { "RR:\($0)" })
        return lines.joined(separator: "\n")
    }

    private func deserializeCacheEntry(_ content: String) -> [String] {
        return content.components(separatedBy: "\n")
            .filter { $0.hasPrefix("RR:") }
            .map { String($0.dropFirst(3)) }
    }
}

// DNS query handler with tenant context
class DNSQueryHandler {
    private let cache: DNSResolverCache
    private let upstreamResolver: String

    init(cache: DNSResolverCache, upstreamResolver: String = "8.8.8.8") {
        self.cache = cache
        self.upstreamResolver = upstreamResolver
    }

    func resolve(tenantId: String, domain: String) throws -> [String] {
        // Check cache first
        if let cached = try cache.readCacheEntry(tenantId: tenantId, domain: domain) {
            return cached
        }

        // Simulate upstream resolution
        let records = performUpstreamQuery(domain: domain)

        // Cache the result
        try cache.writeCacheEntry(tenantId: tenantId, domain: domain, records: records)

        return records
    }

    private func performUpstreamQuery(domain: String) -> [String] {
        // Simulated DNS resolution
        return ["A:93.184.216.34", "AAAA:2606:2800:220:1:248:1893:25c8:1946"]
    }
